// Invested assets only: buys enter the sleeve; sales and income leave it.
// Account cash is outside this valuation boundary. Never treat bank transfers as buys.
function tradeSettlement(t) {
 if(!Number.isFinite(t.amount)||t.amount<0||!['A','S'].includes(t.side))return {amount:null,issue:'İşlem nakit tutarı veya yönü geçersiz.'};
 // A separately posted withholding debit is deducted once, independently of fees.
 if(t.withholdingTax!=null){
  if(!Number.isFinite(t.withholdingTax)||t.withholdingTax<0||t.side!=='S'||!['excluded','included'].includes(t.withholdingTreatment))return {amount:null,issue:'Satış stopajı veya nakit tutarına dahil edilme durumu geçersiz.'};
  const settlement=tradeSettlement({...t,withholdingTax:undefined}),tax=t.withholdingTreatment==='excluded'?t.withholdingTax:0;
  if(settlement.amount==null)return settlement;
  return settlement.amount>=tax?{...settlement,amount:settlement.amount-tax,taxAdjustment:tax}:{amount:null,issue:'Stopaj net satış tutarını aşıyor.'};
 }
 if(t.cashTreatment==='fee-excluded'){
  if(!Number.isFinite(t.fee)||t.fee<0)return {amount:null,issue:'Ayrı kesilen işlem ücreti eksik.'};
  const amount=t.amount+(t.side==='A'?t.fee:-t.fee);
  return amount>=0?{amount,adjustment:t.fee}:{amount:null,issue:'İşlem ücreti satış tutarını aşıyor.'};
 }
 // The crypto statement's cash amount already includes the fee; do not deduct it twice.
 if(t.fee>0&&t.institution!=='Midas Kripto')return {amount:null,issue:'İşlem tutarının ücreti içerip içermediği teyit edilmeli.'};
 return {amount:t.amount,adjustment:0};
}
