 const problems=[...issues,...(valid?[]:['Değer, işlem tutarı veya işlem tarihi geçersiz.'])];
 const method='modified-dietz',methodNotes=[];
 if(problems.length)return {gain:null,returnPct:null,capital:null,netFlow:null,status:'missing',issues:problems,method,methodNotes,diagnostics:null};
 const netFlow=flows.reduce((n,f)=>n+f.amount,0),capital=before+flows.reduce((n,f)=>n+f.amount*(days-f.day)/days,0),gain=after-before-netFlow;
 const daily=new Map();flows.forEach(f=>daily.set(f.day,(daily.get(f.day)||0)+f.amount));
