 const nonzero=[...daily].filter(([,amount])=>Math.abs(amount)>1e-8),largest=nonzero.reduce((m,[,amount])=>Math.max(m,Math.abs(amount)),0);
 const valuationNeededDays=nonzero.filter(([,amount])=>before===0||Math.abs(amount)/before>=PERFORMANCE_FLOW_REVIEW_THRESHOLD).map(([day])=>day).sort((a,b)=>a-b);
