 let date=text.match(/^(\d{4})-(\d{2})-(\d{2})(?:\b|T)/);if(date)return Date.UTC(+date[1],+date[2]-1,+date[3]);
 date=text.match(/^(\d{1,2})[/.](\d{1,2})[/.](\d{2}|\d{4})(?:\b|$)/);if(date)return Date.UTC(+date[3]+(date[3].length===2?2000:0),+date[2]-1,+date[1]);
