const UI_ICON_ASSETS = {"house":"data:image/svg+xml;base64,","briefcase-business":"data:image/svg+xml;base64,","chart-no-axes-combined":"data:image/svg+xml;base64,","chart-pie":"data:image/svg+xml;base64,","gem":"data:image/svg+xml;base64,","bitcoin":"data:image/svg+xml;base64,","globe":"data:image/svg+xml;base64,","arrow-left-right":"data:image/svg+xml;base64,","file-chart-column":"data:image/svg+xml;base64,","layers":"data:image/svg+xml;base64,","coins":"data:image/svg+xml;base64,"};
const SECTION_ICONS={'Ana Sayfa':'house','Portföy':'briefcase-business','Hisse Senetleri':'chart-no-axes-combined','Yatırım Fonları':'chart-pie','Kıymetli Madenler':'gem','Bitcoin':'bitcoin',"ETF'ler":'globe','VOO (ETF)':'globe','Kapanan Pozisyonlar':'briefcase-business','İşlem Geçmişi':'arrow-left-right','Temettüler':'coins','Ayı Güncelle':'arrow-left-right','Raporlar':'file-chart-column'};
function UiIcon({name,size=20,style={}}) {
 const src=UI_ICON_ASSETS[name]||UI_ICON_ASSETS.layers;
 return <span aria-hidden="true" data-ui-icon={name} style={{display:'inline-block',width:size,height:size,minWidth:size,flexShrink:0,verticalAlign:'middle',backgroundColor:'currentColor',maskImage:`url("${src}")`,WebkitMaskImage:`url("${src}")`,maskPosition:'center',WebkitMaskPosition:'center',maskSize:'contain',WebkitMaskSize:'contain',maskRepeat:'no-repeat',WebkitMaskRepeat:'no-repeat',...style}}/>;
}
function SectionIcon({section,size=20,style={}}){
 if(section==='Bitcoin')return <img data-section-icon="Bitcoin" src={ASSET_LOGOS.Bitcoin} alt="" aria-hidden="true" width={size} height={size} style={{display:'inline-block',width:size,height:size,minWidth:size,flexShrink:0,objectFit:'contain',verticalAlign:'middle',...style}}/>;
 return <UiIcon name={SECTION_ICONS[section]||'layers'} size={size} style={style}/>;
}
