const FUND_BRAND_LOGOS = {"is":"data:image/png;base64,","ak":"data:image/png;base64,","ata":"data:image/png;base64,","marmara":"data:image/png;base64,","aktif":"data:image/png;base64,","yapi":"data:image/png;base64,","deniz":"data:image/png;base64,","qnb":"data:image/png;base64,","garanti":"data:image/svg+xml;base64,","inveo":"data:image/png;base64,","hsbc":"data:image/png;base64,","osmanli":"data:image/png;base64,","strateji":"data:image/png;base64,","tacirler":"data:image/png;base64,","ziraat":"data:image/png;base64,","azimut":"data:image/png;base64,","neo":"data:image/png;base64,","rota":"data:image/png;base64,","nurol":"data:image/png;base64,","pardus":"data:image/png;base64,","one":"data:image/png;base64,","teb":"data:image/svg+xml;base64,"};
const FUND_BRAND_BY_CODE = {"TGE":"is","IPV":"is","ITP":"is","IJC":"is","IEV":"is","KPH":"is","TTA":"is","AES":"ak","ZFB":"ak","APLIB.F":"ak","AAV":"ata","RTG":"ata","JET":"ata","URA":"ata","MAC":"marmara","MKG":"aktif","CPU":"aktif","GPT":"aktif","YTD":"yapi","YJK":"yapi","YZG":"yapi","DBH":"deniz","DHM":"deniz","DMG":"deniz","DVT":"deniz","OJT":"qnb","OLD":"qnb","GID":"garanti","GVI":"garanti","GBG":"inveo","GJB":"inveo","HVS":"hsbc","OPH":"osmanli","AN1":"strateji","TCD":"tacirler","ZDZ":"ziraat","GSP":"azimut","NHY":"neo","CPT":"rota","NPH":"nurol","KHA":"pardus","BDS":"pardus","GO9":"one","ICF":"teb"};
function AssetIcon({code,group,size=30}) {
 const bitcoin=code==='Bitcoin'||code==='BTC';
 const logo=ASSET_LOGOS[code]||FUND_BRAND_LOGOS[FUND_BRAND_BY_CODE[code]];
 const metal=group==='Kıymetli Madenler',color=metal?'#f1cc72':group==='Yatırım Fonları'?'#7fb1ff':'#48dabc';
 return <span aria-hidden="true" style={{display:'inline-flex',alignItems:'center',justifyContent:'center',width:size,height:size,minWidth:size,borderRadius:8,background:bitcoin?'transparent':logo?'#fff':color+'18',border:bitcoin?'none':logo?'1px solid #ffffff22':'1px solid '+color+'55',color,fontSize:17,fontWeight:500,marginRight:9,verticalAlign:'middle',lineHeight:1,overflow:'hidden'}}>{logo?<img src={logo} alt="" width={size} height={size} style={{width:bitcoin?20:'100%',height:bitcoin?20:'100%',objectFit:'contain',padding:FUND_BRAND_BY_CODE[code]?2:0}}/>:<UiIcon name={code==='Çeyrek Altın'?'coins':code==='VOO'?'globe':SECTION_ICONS[group]||'chart-no-axes-combined'} size={Math.round(size*.64)}/>}</span>;
}

function AssetIdentity({code,name,group,onClick}) {
 const Tag=onClick?'button':'span';
 const category=FUND_BRAND_BY_CODE[code]?fundTheme(code):(group||'Varlık');
 return <span className="asset-id"><Tag className={onClick?'pd-link asset-id-main':'asset-id-main'} data-asset-code={code} {...(onClick?{type:'button',onClick,'aria-label':code+' · '+name}: {})}><AssetIcon code={code} group={group} size={30}/><span className="asset-id-copy"><span className="asset-id-heading"><strong className="asset-id-code">{code}</strong><span className="asset-id-name" lang="tr">{name&&name!==code?name:''}</span></span><span className="asset-id-meta"><span className="asset-id-category">{category}</span></span></span></Tag></span>;
}

function roundedAxis(values) {
 const max=Math.max(...values,1),rough=max*1.12/4,power=10**Math.floor(Math.log10(rough));
 const step=([1,2,2.5,5,10].find(v=>v>=rough/power)||10)*power;
 const top=Math.ceil(max*1.12/step)*step;
 return {top,step,ticks:Array.from({length:Math.round(top/step)+1},(_,i)=>i*step)};
}
function ValueChart({points,format,labelFormat=format,className='pd-chart',filled=false}) {
 const {top,ticks}=roundedAxis(points.map(p=>p.value));
 const xy=(p,i)=>[90+i*650/Math.max(points.length-1,1),215-p.value/top*180];
 const path=points.map((p,i)=>`${i?'L':'M'}${xy(p,i).join(',')}`).join(' ');
 return <div style={{overflowX:'auto'}}><svg className={className} style={{minWidth:640,display:'block'}} viewBox="0 0 790 265" role="img" aria-label="Aylık portföy değerleri ve tutarları">
 <defs><linearGradient id="valueFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#12e6b1" stopOpacity=".35"/><stop offset="1" stopColor="#12e6b1" stopOpacity="0"/></linearGradient></defs>
 {ticks.map(v=><g key={v}><line x1="90" x2="750" y1={215-v/top*180} y2={215-v/top*180} stroke="#193c52"/><text x="4" y={219-v/top*180} fill="#91aec2" fontSize="11">{format(v)}</text></g>)}
 {filled&&<path d={`${path} L ${xy(points[points.length-1],points.length-1)[0]} 215 L 90 215 Z`} fill="url(#valueFill)"/>}<path d={path} fill="none" stroke="#12e6b1" strokeWidth="3"/>{points.map((p,i)=>{const [x,y]=xy(p,i);return <g key={p.label}><circle cx={x} cy={y} r="4" fill="#12e6b1"><title>{`${p.label}: ${labelFormat(p.value)}`}</title></circle><text x={x} y={i%2?y+23:y-14} textAnchor={i===0?'start':i===points.length-1?'end':'middle'} fill="#ddfff7" stroke="#061c30" strokeWidth="3" paintOrder="stroke" fontSize="11" fontWeight="600">{labelFormat(p.value)}</text><text x={x} y="251" textAnchor="middle" fill="#a9c0d0" fontSize="12">{p.label.slice(0,3)}</text></g>})}</svg></div>;
}

