  const seenIds=new Set(),seenTrades=new Set(),duplicateKeys=new Set();for(const t of monthTrades){const fingerprint=JSON.stringify([t.date,t.time||'',t.code,t.institution,t.side,t.qty,t.amount]);if((t.id&&seenIds.has(t.id))||seenTrades.has(fingerprint))duplicateKeys.add(key(t));if(t.id)seenIds.add(t.id);seenTrades.add(fingerprint)}
