   const conversion=b.bookCurrency==='USD'?fx:1,cash=tradeSettlement(t),amount=cash.amount==null?null:cash.amount/conversion;
   if(duplicateKeys.has(id)){b.blocked=true;b.notes.push('Tekrarlanan işlem kaydı kontrol bekliyor.')}
   if(t.source){b.notes.push('Kaynak: '+t.source);if(t.sourceNote)b.notes.push(t.sourceNote)}
