const INVESTOR_QUOTES = [{"text":"Başkaları açgözlüyken korkulu, başkaları korkuluyken açgözlü olmaya çalışırız.","author":"Warren Buffett","source":"https://www.berkshirehathaway.com/letters/1986.html","sourceLabel":"Berkshire Hathaway · 1986 hissedar mektubu"},{"text":"İyi yönetilen harika işletmelerde en sevdiğimiz elde tutma süresi sonsuzdur.","author":"Warren Buffett","source":"https://www.berkshirehathaway.com/letters/1988.html","sourceLabel":"Berkshire Hathaway · 1988 hissedar mektubu"},{"text":"Karamsarlığın en yoğun olduğu zaman alım, iyimserliğin en yoğun olduğu zaman satış için en iyi zamandır.","author":"John Templeton","source":"https://www.franklintempletonme.com/insights/investor-education/templeton-maxims","sourceLabel":"Franklin Templeton · Templeton Maxims, 7"},{"text":"Neye sahip olduğunuzu ve nasıl bir fon tuttuğunuzu iyi anlamalısınız.","author":"Peter Lynch","source":"https://www.fidelity.com/bin-public/060_www_fidelity_com/documents/learning-center/110322%20rewards%20exclusive_UnderstandtheChange-Transcript_%20F.pdf","sourceLabel":"Fidelity · 3 Kasım 2022 konuşması, sayfa 4"},{"text":"Getiriler söz konusu olduğunda zaman dostunuzdur; maliyetler söz konusu olduğunda ise düşmanınızdır.","author":"John C. Bogle","source":"https://www.vanguard.com.au/personal/learn/smart-investing/understand-the-basics/enduring-wisdom-of-john-bogle-in-five-quotes","sourceLabel":"Vanguard · The enduring wisdom of John C. Bogle in five quotes"},{"text":"Harika bir şirketi makul fiyata almak, sıradan bir şirketi harika fiyata almaktan çok daha iyidir.","author":"Warren Buffett","source":"https://www.berkshirehathaway.com/letters/1989.html","sourceLabel":"Berkshire Hathaway · 1989 hissedar mektubu"},{"text":"Bir hisseyi on yıl tutmaya istekli değilseniz, on dakika tutmayı bile düşünmeyin.","author":"Warren Buffett","source":"https://www.berkshirehathaway.com/letters/1996.html","sourceLabel":"Berkshire Hathaway · 1996 hissedar mektubu"},{"text":"Maçları, gözünü skor tabelasından ayırmayanlar değil, oyun alanına odaklananlar kazanır.","author":"Warren Buffett","source":"https://www.berkshirehathaway.com/letters/2013ltr.pdf","sourceLabel":"Berkshire Hathaway · 2013 hissedar mektubu"},{"text":"Fiyat ödediğinizdir; değer ise aldığınızdır.","author":"Benjamin Graham","source":"https://www.berkshirehathaway.com/letters/2008ltr.pdf","sourceLabel":"Berkshire Hathaway · 2008 mektubunda Buffett’ın Graham’dan aktardığı söz"},{"text":"En büyük yatırım hataları, bilgiden veya analizden değil, psikolojik etkenlerden kaynaklanır.","author":"Howard Marks","source":"https://academic.oup.com/columbia-scholarship-online/book/29783/chapter-abstract/251820445","sourceLabel":"The Most Important Thing · Bölüm 10, Columbia University Press"},{"text":"Yatırımda en önemli organ beyniniz değil, midenizdir.","author":"Peter Lynch","source":"https://www.fidelity.com/bin-public/060_www_fidelity_com/documents/learning-center/Transcript_Portfolio%20Management%20Team_v2.pdf","sourceLabel":"Fidelity · Insights from Portfolio Management Team, sayfa 3"},{"text":"“Bu kez farklı”, piyasanın en pahalı sözlerindendir.","author":"John Templeton","source":"https://www.franklintempletonme.com/insights/investor-education/templeton-maxims","sourceLabel":"Franklin Templeton · Templeton Maxims, 6"}];
function InvestorQuote(){
 const [index,setIndex]=useState(()=>Math.floor(Math.random()*INVESTOR_QUOTES.length)),seen=React.useRef(new Set([index])),quote=INVESTOR_QUOTES[index];
 const next=()=>{
  let choices=INVESTOR_QUOTES.map((_,i)=>i).filter(i=>i!==index&&!seen.current.has(i));
  if(!choices.length){seen.current=new Set([index]);choices=INVESTOR_QUOTES.map((_,i)=>i).filter(i=>i!==index);}
  const selected=choices[Math.floor(Math.random()*choices.length)];seen.current.add(selected);setIndex(selected);
 };
 return <section className="pt-foot pt-investor-quote" data-investor-quote={index} aria-label="Yatırımcı sözü"><button className="pt-quote-card" type="button" onClick={next} aria-label="Başka bir yatırımcı sözü göster"><span className="pt-quote-text" aria-live="polite">“{quote.text}”</span><span className="pt-quote-author">{quote.author}</span></button></section>;
}

function PortfolioExport({idx,currency,goal=DEFAULT_GOAL}) {
 const [message,setMessage]=useState(''),[error,setError]=useState(false);
 const download=(allMonths,event)=>{try{setError(false);const bytes=portfolioXlsx(buildPortfolioExport(idx,currency,allMonths,goal)),blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Portfoy-'+(allMonths?'Tum-Gecmis':DISPLAY_DATA[MONTH_ORDER[idx]].report_date.split('.').reverse().join('-'))+'-'+currency+'.xlsx';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);event.currentTarget.closest('details').open=false;setMessage('Excel dosyası hazırlandı.')}catch(e){setError(true);setMessage('Dosya hazırlanamadı. Yeniden deneyebilirsin.')}};
 return <div className="pt-export"><details><summary className="pt-select" aria-label="Dışa aktar"><UiIcon name="download" size={16}/><span className="pt-export-label">Dışa aktar</span></summary><div className="pt-export-menu"><button type="button" onClick={e=>download(false,e)}>Bu ayı Excel’e aktar<small>{DISPLAY_DATA[MONTH_ORDER[idx]].display_name} · {currency==='USD'?'USD':'TL'}</small></button><button type="button" onClick={e=>download(true,e)}>Tüm geçmişi Excel’e aktar<small>Tüm portföy ayları ve temettü geçmişi</small></button><p>Arama ve tema filtrelerinden bağımsızdır.</p></div></details>{message&&<span className="pt-export-status" role={error?'alert':'status'}>{message}</span>}</div>;
}

const DEFAULT_GOAL={amount:TARGET_TRY,currency:'TRY'};
function goalMetrics(totalTry,fx,goal=DEFAULT_GOAL){
 const value=goal.currency==='USD'?totalTry/fx:totalTry;
 return {value,remaining:Math.max(0,goal.amount-value),ratio:value/goal.amount};
}
function PortfolioGoal({totalTry,fx,goal=DEFAULT_GOAL,onChange,className='pt-card'}){
 const [editing,setEditing]=useState(false),[amount,setAmount]=useState(''),[unit,setUnit]=useState('TRY'),[error,setError]=useState('');
 const metrics=goalMetrics(totalTry,fx,goal),cash=v=>(goal.currency==='USD'?'$':'₺')+number(v,goal.currency==='USD'?2:0);
 const title=goal.amount===10000000&&goal.currency==='TRY'?'10 Milyon TL Hedefi':number(goal.amount,2)+' '+(goal.currency==='USD'?'USD':'TL')+' Hedefi';
 const open=()=>{setAmount(String(goal.amount));setUnit(goal.currency);setError('');setEditing(v=>!v)};
 const save=e=>{e.preventDefault();const value=Number(amount);if(!Number.isFinite(value)||value<=0){setError('Sıfırdan büyük bir hedef gir.');return}onChange({amount:value,currency:unit});setEditing(false);setError('')};
 return <section className={className+' pt-goal'} data-portfolio-goal="true"><div className="pt-goal-heading"><h3>{title}</h3><button type="button" className="pt-goal-settings" aria-label="Hedefi düzenle" aria-expanded={editing} onClick={open}><span aria-hidden="true">⚙</span></button></div>{editing&&<form className="pt-goal-form" onSubmit={save}><label>Hedef tutarı<input aria-label="Hedef tutarı" type="number" min="0.01" step="any" required value={amount} onChange={e=>setAmount(e.target.value)}/></label><label>Para birimi<select aria-label="Hedef para birimi" value={unit} onChange={e=>setUnit(e.target.value)}><option value="TRY">₺ TL</option><option value="USD">$ USD</option></select></label>{error&&<p role="alert">{error}</p>}<div><button type="submit">Kaydet</button><button type="button" onClick={()=>setEditing(false)}>Vazgeç</button></div></form>}<div className="pt-row"><span>Tamamlanan</span><strong className="pt-positive" data-goal-ratio={metrics.ratio}>{number(metrics.ratio*100,1)}%</strong></div><div className="pt-bar" role="progressbar" aria-label="Hedef ilerlemesi" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.min(100,metrics.ratio*100)}><div style={{width:`${Math.min(100,metrics.ratio*100)}%`}}/></div><div className="pt-small">Kalan: {cash(metrics.remaining)}</div>{goal.currency==='USD'&&<div className="pt-note">Seçilen ayın kayıtlı dolar kuru kullanılır.</div>}</section>;
}


// Local monthly ledger. No remote calls; only append validated months.
