function updClone(x){return JSON.parse(JSON.stringify(x))}
function updNum(v){if(typeof v==='number')return Number.isFinite(v)?v:NaN;const s=String(v??'').trim().replace(/[₺$%\s]/g,'');if(!s)return NaN;if(!/^[+-]?[\d.,]+$/.test(s))return NaN;return Number(s.includes(',')?s.replace(/\./g,'').replace(',','.'):s)}
function updISO(v){if(v instanceof Date&&Number.isFinite(+v))return String(v.getFullYear()).padStart(4,'0')+'-'+String(v.getMonth()+1).padStart(2,'0')+'-'+String(v.getDate()).padStart(2,'0');const s=String(v??'').trim();if(/^\d{4}-\d{2}-\d{2}$/.test(s)){const d=new Date(s+'T00:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===s?s:null}const m=s.match(/^(\d{2})[/.](\d{2})[/.](\d{2}|\d{4})(?:\s|$)/);return m?updISO((m[3].length===2?'20':'')+m[3]+'-'+m[2]+'-'+m[1]):null}
function updPeriod(m){return m.report_date.split('.').reverse().join('-').slice(0,7)}
function updNext(period){const [y,m]=period.split('-').map(Number);return new Date(Date.UTC(y,m,1)).toISOString().slice(0,7)}
function updEnd(period){const [y,m]=period.split('-').map(Number);return new Date(Date.UTC(y,m,0)).toISOString().slice(0,10)}
function updKey(p){return JSON.stringify([p.platform,p.code])}
function updIgnored(p){return ['QUICK','CITAS'].includes(p.code)||p.platform==='İş Bankası'&&['BINHO','KOCMT','PATEK'].includes(p.code)||!UPD_PLATFORMS.includes(p.platform)}
