function updGoldTrade(entry,positions=[]){const spec=updGoldSpec(entry,positions);if(!spec)return entry;const qty=updNum(entry.qty),price=updNum(entry.price);if(!Number.isFinite(spec.grams)||spec.grams<=0||!spec.code)throw Error('Madenin ayarını / milyemini seç.');if(spec.unit==='adet'&&!Number.isInteger(qty))throw Error('Sarrafiye miktarı tam adet olmalı.');if(!(qty>0)||!(price>0))throw Error('Gram/adet ve birim fiyat sıfırdan büyük olmalı.');return {...entry,code:spec.code,name:spec.name,group:'Kıymetli Madenler',currency:'TRY',qty:qty/spec.scale,price:price*spec.scale,grams:spec.grams,unit:spec.storageUnit,purity:spec.purity,metal:spec.metal};}
function physicalQuantityText(p,digits=6){if(p.platform!=='Fiziki Altın'&&p.institution!=='Fiziki Altın')return number(p.qty,digits);if(p.code==='Bilezik'&&p.unit!=='gram')return number(p.qty*UPD_LEGACY_BRACELET_GRAMS,digits)+' g';return number(p.qty,digits)+(p.unit==='gram'?' g':' adet')}

function physicalPriceScale(p){return p.platform==='Fiziki Altın'&&p.code==='Bilezik'&&p.unit!=='gram'&&p.qty>0?UPD_LEGACY_BRACELET_GRAMS:1}
function physicalTradeQuantity(t){return t.institution==='Fiziki Altın'?number(t.qty*(t.code==='Bilezik'&&t.unit!=='gram'?UPD_LEGACY_BRACELET_GRAMS:1),8)+(t.code==='Bilezik'&&t.unit!=='gram'?' g':t.unit==='gram'?' g':' adet'):number(t.qty,8)}
function physicalTradePriceScale(t){return t.institution==='Fiziki Altın'&&t.code==='Bilezik'&&t.unit!=='gram'?UPD_LEGACY_BRACELET_GRAMS:1}

function updOpening(){const m=DISPLAY_DATA[MONTH_ORDER.at(-1)];return monthPositions(m).filter(p=>!updIgnored(p)).map(p=>({code:p.code,name:p.name||p.code,platform:p.platform,group:p.group,native:p.native||'TRY',qty:p.qty,cost:p.cost,price:p.price,grams:p.grams&&p.qty?p.grams/p.qty:null,unit:p.unit||null,purity:p.purity||null,metal:p.metal||null,sector:p.sector||''}))}
function updNewDraft(){const m=DISPLAY_DATA[MONTH_ORDER.at(-1)];return {schema:UPD_SCHEMA,base:UPD_BASE,period:updNext(updPeriod(m)),custody:[],market:{usd:'',gold:'',silver:'',bist:'',cpi:''},positions:updOpening().map(p=>({...p,openingQty:p.qty,qty:String(p.qty),price:'',confirmed:false})),trades:[],income:[],files:[],reviewed:false}}
function updLots(code,end,history){const lots=[];for(const t of history.filter(t=>t.code===code&&t.date<=end).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))){if(t.side==='A')lots.push({qty:t.qty,cost:t.amount});else if(t.side==='S'){let q=t.qty;while(q>1e-8&&lots.length){const l=lots[0],take=Math.min(q,l.qty);l.cost*=1-take/l.qty;l.qty-=take;q-=take;if(l.qty<1e-8)lots.shift()}if(q>1e-7)return null}}return lots}
function updFingerprint(t){return JSON.stringify([t.date,t.time||'',t.code,t.platform,t.side,t.qty,t.amount,t.currency])}
function updMergeRows(old,rows){const seen=new Set(old.map(updFingerprint)),accepted=[],duplicates=[];for(const row of rows){const key=updFingerprint(row);if(seen.has(key)){duplicates.push(row);continue}seen.add(key);accepted.push(row)}return {rows:[...old,...accepted],duplicates}}
