 updSafeDraft(d);
 const errors=[],warnings=[],add=m=>{if(!errors.includes(m))errors.push(m)},finite=Number.isFinite,fx=updNum(d.market?.usd),gold=updNum(d.market?.gold),silver=updNum(d.market?.silver),bist=updNum(d.market?.bist),cpi=updNum(d.market?.cpi);
