 const anomalies=[];if(Number.isFinite(fx)&&Math.abs(fx/monthRate(previous)-1)>.2)anomalies.push('USD/TL kuru önceki aydan %20’den fazla farklı.');if(Number.isFinite(gold)&&Math.abs(gold/previous.gold_reference.price-1)>.3)anomalies.push('Gram altın fiyatı önceki aydan %30’dan fazla farklı.');if(!d.reviewed)add('Tüm hesapların işlem ve ay sonu kayıtlarını gözden geçirdiğini onayla.');
