  trades.push({id:tradeId,date:legacyDate,time:t.time||'',code:t.code,name:b.p.name,group:b.p.group,institution:t.platform,side,currency,qty,unit:b.p.unit||(b.p.platform==='Fiziki Altın'?(b.p.code==='Bilezik'?'legacy-piece':'adet'):null),purity:b.p.purity||null,price:price*multiplier,fee:fee*multiplier,amount:amount*multiplier,feeTreatment:'included',withholding:tax*multiplier,withholdingTreatment:'included',sourceFile:t.source||'Elle girilen işlem',month:d.period,mi:MONTH_ORDER.length});
