function updBoot(){for(const d of PUBLISHED_UPDATES){try{updSafeDraft(d);updInstall(d,false)}catch(e){UPD_BOOT_ISSUES.push('Yayımlanan ay yüklenemedi: '+e.message);return}}try{const saved=JSON.parse(localStorage.getItem('portfolio-updates-v1')||'null');if(saved){if(saved.schema!==UPD_SCHEMA||saved.base!==UPD_BASE||!Array.isArray(saved.months))throw Error('Tarayıcı yedeği sürüm uyumsuz.');for(const d of saved.months){const existing=UPD_ACTIVE.find(x=>x.period===d.period);if(existing){if(JSON.stringify(existing)!==JSON.stringify(d))throw Error(d.period+': yayımlanan kayıt ile tarayıcı kaydı çelişiyor.');continue}updInstall(d,false)}}}catch(e){if(e.name!=='ReferenceError')UPD_BOOT_ISSUES.push('Tarayıcı kaydı açılamadı. Bu oturumdaki değişiklikler için yedek indir.')}}
