function updCellNum(v){if(typeof v==='number')return v;const s=String(v??'').replace(/\s*(TRY|TL|USD)$/i,'').trim();return updNum(s.includes(',')?s:/^[+-]?[1-9]\d{0,2}(?:\.\d{3})+$/.test(s)?s.replace(/\./g,''):s)}
