  trades.push({code,platform:'İş Bankası',group:updGroup(code,'İş Bankası')||'Yatırım Fonları',name:FULL_NAMES[code]||code,date,side,qty,price,amount:Number.isFinite(net)?net:gross-tax,fee:0,tax,currency:'TRY',source});continue;
