 const code=updCode(get('Kod','Sembol'));if(!code)continue;const inst=String(get('Kurum')||platform),known=updKnown(code,inst),group=String(get('Varlık Türü')||updGroup(code,inst)||''),currency=String(get('Para Birimi')||known?.native||'TRY').toUpperCase(),date=updISO(get('Tarih')),sideText=String(get('İşlem'));
