function TradeAssetPicker({positions,onPick}){
 const [query,setQuery]=useState('');const opening=new Set(updOpening().map(updKey)),match=p=>!query||updNorm(p.code+' '+p.name+' '+p.platform+' '+p.group).includes(updNorm(query));
 const previous=positions.filter(p=>opening.has(updKey(p))&&match(p)),added=positions.filter(p=>!opening.has(updKey(p))&&match(p));
 const catalogue=useMemo(()=>{const previousTrades=RECORDED_TRADES.filter(t=>t.institution!=='Fiziki Altın'),history=new Map(previousTrades.map(t=>[t.code,t]));const fundCodes=new Set([...FUND_CODES,...Object.keys(FUND_BRAND_BY_CODE),...Object.keys(BANK_FUND_HISTORY_NAMES),...VERIFIED_BANK_FUND_HISTORY.map(t=>t.code),...previousTrades.filter(t=>['Yatırım Fonları','Kıymetli Madenler'].includes(t.group)).map(t=>t.code)]);const names={...UPD_BIST_NAMES,...Object.fromEntries(previousTrades.map(t=>[t.code,t.name||t.code])),...BANK_FUND_HISTORY_NAMES,...FULL_NAMES};const codes=new Set([...Object.keys(names),...fundCodes,'VOO','Bitcoin']);return [...codes].filter(code=>(code==='Bitcoin'||/^[A-Z][A-Z0-9.]{1,11}$/.test(code))&&!['QUICK','CITAS'].includes(code)).map(code=>({code,name:names[code]||code,platform:code==='Bitcoin'?'Midas Kripto':'Midas',group:history.get(code)?.group||(code==='Bitcoin'?'Bitcoin':code==='VOO'?"ETF'ler":fundCodes.has(code)?isPreciousFund({code})?'Kıymetli Madenler':'Yatırım Fonları':'Hisse Senetleri'),native:code==='VOO'?'USD':'TRY'})).sort((a,b)=>a.code.localeCompare(b.code,'tr'))},[]);
 const candidates=catalogue.filter(match).filter(p=>!positions.some(x=>updKey(x)===updKey(p))),stocks=candidates.filter(p=>p.group==='Hisse Senetleri').slice(0,40),funds=candidates.filter(p=>['Yatırım Fonları','Kıymetli Madenler'].includes(p.group)).slice(0,40),other=candidates.filter(p=>['Bitcoin',"ETF'ler"].includes(p.group));
 const physical=UPD_GOLD_PRODUCTS.filter(p=>!query||updNorm(p.label).includes(updNorm(query)));
 const option=(p,prefix)=><option key={prefix+updKey(p)} value={prefix+JSON.stringify([p.platform,p.code])}>{p.code} · {p.name!==p.code?p.name+' · ':''}{p.platform}{p.platform==='Fiziki Altın'?' · '+number(updNum(p.qty)*updDraftQuantity(p).scale,4)+' '+updDraftQuantity(p).unit:''}</option>;
 const choose=e=>{const value=e.target.value;if(!value)return;if(value==='manual'){onPick({kind:'manual',query});return}if(value.startsWith('metal:')){onPick({kind:'metal',product:value.slice(6)});return}const list=value.startsWith('catalog:')?catalogue:positions,key=value.slice(value.indexOf(':')+1);const p=list.find(p=>JSON.stringify([p.platform,p.code])===key);if(p)onPick({kind:value.startsWith('catalog:')?'catalog':'existing',position:p})};
 return <div className="pt-asset-picker"><label>Varlık ara<input aria-label="Varlık ara" placeholder="Hisse, fon, gram altın, gümüş…" value={query} onChange={e=>setQuery(e.target.value)}/></label>{query.trim()&&<div className="pt-asset-suggestions" aria-label="Varlık önerileri">{[...previous,...added,...candidates].slice(0,12).map(p=><button type="button" key={updKey(p)} onClick={()=>{onPick({kind:positions.some(x=>updKey(x)===updKey(p))?'existing':'catalog',position:p});setQuery('')}}><strong>{p.code}</strong><span>{p.name}</span></button>)}{physical.map(p=><button type="button" key={p.id} onClick={()=>{onPick({kind:'metal',product:p.id});setQuery('')}}>{p.label}</button>)}{!previous.length&&!added.length&&!candidates.length&&!physical.length&&<span>Eşleşme yok. Aşağıdan elle ekleyebilirsin.</span>}</div>}<label>Varlık seç<select aria-label="İşlem için mevcut varlık" value="" onChange={choose}><option value="">Arama sonucundan varlık seç</option>{previous.length>0&&<optgroup label="Önceki aydan kalanlar">{previous.map(p=>option(p,'existing:'))}</optgroup>}{added.length>0&&<optgroup label="Bu ay eklenenler">{added.map(p=>option(p,'existing:'))}</optgroup>}{physical.length>0&&<optgroup label="Fiziki altın / gümüş türleri">{physical.map(p=><option key={p.id} value={'metal:'+p.id}>{p.label} · {p.unit}</option>)}</optgroup>}{stocks.length>0&&<optgroup label="Diğer hisseler">{stocks.map(p=>option(p,'catalog:'))}</optgroup>}{funds.length>0&&<optgroup label="Diğer fonlar">{funds.map(p=>option(p,'catalog:'))}</optgroup>}{other.length>0&&<optgroup label="ETF / Bitcoin">{other.map(p=>option(p,'catalog:'))}</optgroup>}<optgroup label="Yeni varlık"><option value="manual">Listede yok · Kodu ve adı elle gir</option></optgroup></select></label><small className="pt-note">Önceki ayın varlıkları üsttedir. BIST endeks kataloğu ve kayıtlı fonlar kod/isimle aranır. Fon listesi tüm piyasayı kapsamaz; eksik kodu elle ekleyebilirsin.</small></div>;
}

function MonthlyUpdater({onCommitted}){
 const fresh=()=>{try{const d=JSON.parse(localStorage.getItem('portfolio-draft-v1')||'null');if(d?.schema===UPD_SCHEMA&&d.base===UPD_BASE&&d.period===updNewDraft().period&&Array.isArray(d.positions)&&Array.isArray(d.trades)&&Array.isArray(d.income)&&Array.isArray(d.files))return updSafeDraft(d)}catch{}return updNewDraft()};
 const [draft,setDraft]=useState(fresh),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[text,setText]=useState(''),[candidate,setCandidate]=useState(null),[source,setSource]=useState(''),[restore,setRestore]=useState(null),[filter,setFilter]=useState(''),[storageError,setStorageError]=useState(''),[uploadStatus,setUploadStatus]=useState(null);
 const [clearPending,setClearPending]=useState(false),[undoDraft,setUndoDraft]=useState(null);
 const emptyTrade={date:updNewDraft().period+'-01',code:'',name:'',platform:'Midas',group:'Hisse Senetleri',side:'A',qty:'',price:'',amount:'',fee:'0',tax:'0',currency:'TRY',time:'',grams:'',goldProduct:'gram',goldPurity:''};
 const [entry,setEntry]=useState(emptyTrade),[pay,setPay]=useState({date:emptyTrade.date,code:'',qty:'',amount:'',currency:'TRY'}),[importPlatform,setImportPlatform]=useState('auto'),[pendingUploads,setPendingUploads]=useState([]);
 useEffect(()=>{try{localStorage.setItem('portfolio-draft-v1',JSON.stringify(draft));setStorageError('')}catch{setStorageError('Bu ortam tarayıcıya kaydetmeye izin vermiyor. Taslak yedeğini indir.')}},[draft]);
 const check=updBuild(draft),change=fn=>{setDraft(d=>{const next=updClone(d);fn(next);next.reviewed=false;next.anomaliesReviewed=false;return next});setNotice('')};
 const setMarket=(k,v)=>change(d=>{d.market[k]=v});
 const merge=(d,rows,positions=[],income=[])=>{const joined=updMergeRows(d.trades,rows);d.trades=joined.rows;const touched=new Set();for(const t of joined.rows){const key=updKey(t);let p=d.positions.find(p=>updKey(p)===key);if(!p){const old=updKnown(t.code,t.platform);p={code:t.code,name:t.name||old?.name||t.code,platform:t.platform,group:t.group||old?.group,native:t.currency||old?.native||'TRY',qty:'0',price:'',cost:null,grams:t.grams||old?.grams||null,unit:t.unit||old?.unit||null,purity:t.purity||old?.purity||null,metal:t.metal||old?.metal||null,confirmed:false};d.positions.push(p)}if(rows.includes(t))touched.add(key)}
  const opening=new Map(updOpening().map(p=>[updKey(p),p.qty]));for(const key of touched){const p=d.positions.find(p=>updKey(p)===key);delete p.qtyInput;p.qty=String((opening.get(key)||0)+d.trades.filter(t=>updKey(t)===key).reduce((s,t)=>s+(t.side==='A'?1:-1)*updNum(t.qty),0));p.confirmed=false}
  for(const p of positions){const old=d.positions.find(x=>updKey(x)===updKey(p));if(old){Object.assign(old,p,{confirmed:false});delete old.qtyInput;delete old.priceInput}else d.positions.push(p)}
  const incSeen=new Set(d.income.map(r=>JSON.stringify([r.date,r.code,r.amount,r.qty,r.currency])));for(const r of income){const id=JSON.stringify([r.date,r.code,r.amount,r.qty,r.currency]);if(!incSeen.has(id)){d.income.push(r);incSeen.add(id)}}return joined.duplicates.length};
 const metalSpec=entry.platform==='Fiziki Altın'?updGoldSpec(entry,draft.positions):null;
 const addTrade=e=>{e.preventDefault();try{const prepared=updGoldTrade(entry,draft.positions),t={...prepared,code:updCode(prepared.code),name:prepared.name||prepared.code,date:updISO(prepared.date),qty:updNum(prepared.qty),price:updNum(prepared.price),amount:updNum(prepared.amount),fee:updNum(prepared.fee),tax:updNum(prepared.tax),source:'Elle girilen işlem'};if(!t.date||t.date.slice(0,7)!==draft.period||![t.qty,t.price,t.amount,t.fee,t.tax].every(Number.isFinite)||t.qty<=0||t.price<=0||t.amount<0){setNotice('Tarih, miktar, fiyat ve nakit tutarını kontrol et.');return}if(updIgnored(t)){setNotice('Bu kurum/varlık tercihin gereği kapsam dışında.');return}change(d=>{merge(d,[t])});setEntry({...emptyTrade,date:draft.period+'-01'});}catch(e){setNotice(e.message)}};
 const loadFiles=async (event,manualPlatform=null)=>{
  if(busy)return;
  const files=Array.from(event.target.files||[]);event.target.value='';if(!files.length)return;
  if(files.length>1&&files.some(f=>/\.json$/i.test(f.name))){setUploadStatus({state:'error',text:'Taslak veya veri yedeğini diğer ekstrelerden ayrı yükle; üzerine yazma öncesinde ayrıca onaylanır.',results:[]});return}setBusy(true);setUploadStatus({state:'loading',text:'Dosyalar okunuyor…',results:[]});
  try{const next=updClone(draft),results=[],pending=[];let added=0,updated=0,payments=0,evidence=0;
   for(let i=0;i<files.length;i++){
    const file=files[i];setUploadStatus({state:'loading',text:(i+1)+' / '+files.length+' · '+file.name+' okunuyor…',results:[...results]});
    const r=await updExtractFile(file,manualPlatform||'auto',draft.period);
    if(r.kind==='draft'||r.kind==='backup'){setRestore(r.kind==='draft'?{draft:r.data.draft}:r.data);setUploadStatus({state:'warning',text:r.label+' tanındı. Uygulamak için aşağıdaki özeti onayla; henüz hiçbir kayıt değiştirilmedi.',results:[],restoreReady:true});setPendingUploads([]);return}
    if(r.needsInstitution){pending.push(file);results.push({name:file.name,state:'warning',text:'Kurum kesin belirlenemedi. Aşağıdaki seçim yalnız bu dosya için gerekli.',messages:r.unknown});continue}

    if(next.files.some(f=>f.hash===r.hash)){results.push({name:file.name,state:'warning',text:'Bu dosya daha önce yüklendi. İkinci kez eklenmedi.'});continue}
    if(r.kind==='custody'){next.custody=next.custody||[];const seen=new Set(next.custody.map(x=>JSON.stringify([x.date,x.time||'',x.isin,x.qty,x.from,x.to,x.description])));let count=0;for(const row of r.custody||[]){const fp=JSON.stringify([row.date,row.time||'',row.isin,row.qty,row.from,row.to,row.description]);if(!seen.has(fp)){seen.add(fp);next.custody.push(row);count++}}evidence+=count;next.files.push({name:file.name,hash:r.hash,unresolved:r.unknown.length>0,resolved:false,messages:r.unknown,imported:count,ignored:r.ignored||0,duplicates:(r.custody?.length||0)-count,kind:'custody',label:r.label});results.push({name:file.name,state:r.unknown.length?'warning':'success',text:r.label+' tanındı. '+count+' yeni teyit kaydı alındı; alım/satım, maliyet ve portföy değeri değiştirilmedi.',messages:r.unknown});continue}
    const incoming=r.trades.filter(t=>!updIgnored(t)),holdings=r.positions.filter(p=>!updIgnored(p));
    const dates=[...new Set([...incoming,...r.income].map(t=>t.date?.slice(0,7)).filter(Boolean))];
    const outside=incoming.some(t=>!t.date||t.date.slice(0,7)!==next.period)||r.income.some(t=>!t.date||t.date.slice(0,7)!==next.period)||r.period&&r.period!==next.period;
    if(outside){const seen=[...new Set([r.period,...dates].filter(Boolean))];results.push({name:file.name,state:'error',text:'Dosya bu aya alınmadı. Açık taslak '+next.period+'; dosyanın dönemi / işlem tarihleri '+(seen.join(', ')||'belirsiz')+'. Geçmiş aylar değiştirilmedi.'});continue}
    const ignored=r.trades.length-incoming.length+r.positions.length-holdings.length,before=next.trades.length,beforeIncome=next.income.length;
    const duplicateCount=merge(next,incoming,holdings,r.income),newTrades=next.trades.length-before,newIncome=next.income.length-beforeIncome;
    added+=newTrades;updated+=holdings.length;payments+=newIncome;
    next.files.push({name:file.name,hash:r.hash,unresolved:r.unknown.length>0||!r.recognized,resolved:false,messages:r.unknown,imported:newTrades+holdings.length+newIncome,ignored,duplicates:duplicateCount});
    const hasRecords=newTrades+holdings.length+newIncome>0,warning=r.unknown.length>0||!r.recognized;
    results.push({name:file.name,state:warning||!hasRecords?'warning':'success',text:hasRecords?r.label+' tanındı. '+newTrades+' yeni alım/satım, '+holdings.length+' ay sonu pozisyonu, '+newIncome+' temettü taslağa alındı. '+duplicateCount+' tekrar, '+ignored+' kapsam dışı kayıt ayıklandı.':r.recognized?'Bu dosyadan yeni kayıt eklenmedi. Kayıtlar daha önce eklenmiş veya kapsam dışında olabilir.':'Dosya biçimi tanınmadı; hiçbir kayıt otomatik eklenmedi. Kurum seçimini ve aşağıdaki açıklamayı kontrol et.',codes:[...new Set([...incoming,...holdings].map(p=>p.code))].slice(0,8),messages:r.unknown});
   }
   next.reviewed=false;next.anomaliesReviewed=false;setDraft(next);setPendingUploads(pending);
   const hasRecords=added+updated+payments+evidence>0,state=results.some(r=>r.state==='error'||r.state==='warning')?'warning':'success';
   const message=hasRecords?added+' yeni işlem, '+updated+' pozisyon, '+payments+' temettü ve '+evidence+' teyit kaydı taslağa alındı. Henüz ana sayfaya kaydedilmedi.':'Taslak değişmedi. Nedenini aşağıdaki dosya sonuçlarında görebilirsin.';
   setUploadStatus({state:hasRecords?state:'warning',text:message,results,added,updated,payments,evidence});setNotice(message);
  }catch(e){const message='Dosya okunamadı: '+e.message+'. Bu yüklemeden hiçbir değişiklik kaydedilmedi.';setUploadStatus({state:'error',text:message,results:[]});setNotice(message)}finally{setBusy(false)}
 };
 const applyText=()=>{change(d=>{Object.assign(d.market,candidate.market);if(candidate.trade)merge(d,[candidate.trade])});setCandidate(null);setText('')};
 const close=()=>{try{updInstall(draft);setNotice(draft.period+' kaydedildi. Şimdi veri yedeğini ve güncel JSX’i indir.');setDraft(updNewDraft());onCommitted(MONTH_ORDER.length-1,false)}catch(e){setNotice(e.message)}};
 const sourceFile=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>8*1024*1024)throw Error('JSX dosyası çok büyük.');const value=await file.text();await updExportJSX(value);setSource(value);setNotice('JSX şablonu doğrulandı.')}catch(e){setNotice(e.message)}};
 const downloadJSX=async()=>{try{if(!source)throw Error('Önce kullandığın PortfolioDashboard.jsx dosyasını seç. Dosyanın kodu çalıştırılmaz.');updDownload('PortfolioDashboard.jsx',await updExportJSX(source),'text/jsx');setNotice('Güncel JSX indirildi. GitHub’daki aynı dosyanın üzerine yükleyebilirsin.')}catch(e){setNotice(e.message)}};
 const loadBackup=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>20*1024*1024)throw Error('Yedek en fazla 20 MB olabilir.');const data=JSON.parse(await file.text());if(data.schema!==UPD_SCHEMA||data.base!==UPD_BASE)throw Error('Yedek bu site sürümüyle uyumlu değil.');if(data.draft){if(data.draft.period!==updNewDraft().period)throw Error('Taslağın ayı sıradaki ay değil.');if(!Array.isArray(data.draft.positions)||!Array.isArray(data.draft.trades)||!Array.isArray(data.draft.income)||!Array.isArray(data.draft.files))throw Error('Taslak yapısı geçersiz.');setRestore({draft:updSafeDraft(data.draft)});}else{updValidateBackup(data);setRestore(data)}setNotice('Yedek kontrol edildi. Uygulamadan önce aşağıdaki özeti incele.')}catch(e){setNotice('Yedek alınmadı: '+e.message)}};
 const restoreBackup=()=>{try{if(restore.draft)setDraft(updClone(restore.draft));else{updRestore(restore);setDraft(updNewDraft());onCommitted(MONTH_ORDER.length-1,false)}setRestore(null);setNotice('Yedek geri yüklendi.')}catch(e){setNotice(e.message)}};
 const input=(label,key,type='text')=><label>{label}<input type={type} required value={entry[key]} onChange={e=>setEntry(v=>({...v,[key]:e.target.value}))}/></label>;
 return <div className="pt-update" data-month-updater="true"><section className="pt-card"><div className="pt-update-heading"><div><h2>Ayı Güncelle</h2><p className="pt-muted">{draft.period} taslağı · Önceki {MONTH_ORDER.length} ay korunur</p></div><span className="pt-update-badge">Cihazında çalışır</span></div><p>Ekstre veya işlemleri ekle, ay sonu fiyatlarını doğrula, kontrollerden sonra ayı kaydet. Sayılarda binlik ayıracı kullanma; ondalık için virgül yaz. Dosyaların bir sunucuya gönderilmez.</p>{UPD_BOOT_ISSUES.map((m,i)=><p role="alert" key={i}>{m}</p>)}{storageError&&<p role="alert">{storageError}</p>}{notice&&<p className="pt-update-notice" role="status" style={{whiteSpace:'pre-wrap'}}>{notice}</p>}{clearPending&&<div className="pt-update-notice" role="alert"><p>{draft.period} taslağındaki {draft.files.length} dosya, {draft.trades.length} işlem, {draft.income.length} gelir ve bu aya ait elle yapılan değişiklikler temizlenecek. Kayıtlı geçmiş aylar korunur.</p><button type="button" disabled={busy} onClick={()=>{setUndoDraft(updClone(draft));setDraft(updNewDraft());setClearPending(false);setPendingUploads([]);setUploadStatus(null);setRestore(null);setCandidate(null);setText('');setEntry({...emptyTrade});setNotice('Taslak temizlendi. Yanlışlıkla temizlediysen bu sayfadan ayrılmadan geri alabilirsin.')}}>Evet, taslağı temizle</button><button type="button" onClick={()=>setClearPending(false)}>Vazgeç</button></div>}<div className="pt-update-actions"><button type="button" disabled={busy} onClick={()=>setClearPending(true)}>Taslağı temizle</button>{undoDraft&&<button type="button" disabled={busy} onClick={()=>{setDraft(undoDraft);setUndoDraft(null);setNotice('Temizlenen taslak geri alındı.')}}>Temizlemeyi geri al</button>}<button onClick={()=>updDownload('Portfoy-Veri-Yedegi.json',JSON.stringify({...updEnvelope(),archive:{order:MONTH_ORDER,months:DISPLAY_DATA,trades:RECORDED_TRADES,income:DIVIDEND_ROWS}},null,2))}>Veri yedeğini indir</button><button onClick={()=>updDownload('Portfoy-Taslak-'+draft.period+'.json',JSON.stringify({schema:UPD_SCHEMA,base:UPD_BASE,draft},null,2))}>Taslağı indir</button><label className="pt-update-upload">Yedeği geri yükle<input type="file" accept=".json" onChange={loadBackup}/></label></div>{restore&&<div className="pt-update-notice"><p>{restore.draft?restore.draft.period+' taslağı mevcut taslağın yerini alacak.':restore.months.filter(d=>!UPD_ACTIVE.some(x=>x.period===d.period)).length+' yeni ay eklenecek. Eski aylar değişmeyecek.'}</p><button onClick={restoreBackup}>Yedeği uygula</button><button onClick={()=>setRestore(null)}>Vazgeç</button></div>}</section>
 <section className="pt-card"><h3>Ay sonu piyasa bilgileri</h3><div className="pt-update-fields">{[['usd','USD / TL kapanış kuru'],['gold','Saf gram altın / TL'],['silver','Saf gram gümüş / TL (fiziki gümüş varsa)'],['bist','BIST 100 aylık getiri %'],['cpi','Aylık TÜFE %']].map(([k,l])=><label key={k}>{l}<input aria-label={l} inputMode="decimal" value={draft.market[k]} onChange={e=>setMarket(k,e.target.value)}/></label>)}</div><details><summary>Yazarak ekle</summary><p className="pt-note">Örnek: “Dolar 50,20; gram altın 6800; BIST100 getirisi -3,2; aylık enflasyon 2,1.” Altın: “2026-10-25 tarihinde 2 çeyrek aldım, tanesi 12.154 TL.”</p><textarea aria-label="Sözel bilgi girişi" rows={3} value={text} onChange={e=>{setText(e.target.value);setCandidate(null)}}/><button onClick={()=>{try{setCandidate(updSpeech(text,draft.period));setNotice('')}catch(e){setNotice(e.message)}}}>Anladığını göster</button>{candidate&&<div className="pt-update-notice"><ul>{Object.entries(candidate.market).map(([k,v])=><li key={k}>{({usd:'USD/TL',gold:'Saf gram altın TL',bist:'BIST100 %',cpi:'TÜFE %'})[k]}: {number(v,4)}</li>)}{candidate.trade&&<li>{candidate.trade.date} · {candidate.trade.qty} çeyrek · Tanesi ₺{number(candidate.trade.price,2)} · Toplam ₺{number(candidate.trade.amount,2)}</li>}</ul><button onClick={applyText}>Bu bilgileri taslağa ekle</button></div>}</details></section>
 <section className="pt-card"><h3>Ekstre ve tablo yükle</h3><p><strong>Yüklenecek ay: {UPD_MONTH_NAMES[Number(draft.period.slice(5))-1]} {draft.period.slice(0,4)}</strong></p><p className="pt-note">1. Dosyaları birlikte yükle. 2. Otomatik tanınan kurum ve belge türünü aşağıdan kontrol et. 3. Alınan kayıtları kontrol et; en alttaki “Ayı kaydet” adımıyla ana sayfaya uygula. Önceki aylara ait dosyalar yeni aya aktarılmaz.</p><p className="pt-note">İş Bankası fon hareketleri Excel’i, tanınan TEFAS satış PDF satırları ve Midas Kripto’nun tanınan metin PDF’i okunur. Midas’ın tanınan hisse/ETF PDF’leri de okunur; bilinmeyen tablo biçimleri için şablon kullanılır. PDF’de temettü adedi yoksa sen tamamlarsın. MKK kayıtları ayrı teyit listesine alınır; alım/satım sayılmaz. Kendi tablon kurum sütunuyla birden fazla hesabı içerebilir. JSON taslak/yedeği ayrıca onaylanarak geri yüklenir. Tanınmayan PDF veya kurumsal işlem otomatik onaylanmaz.</p><div className="pt-update-actions"><span className="pt-note">Kurum ve belge türü içerikten otomatik belirlenir.</span><label className="pt-update-upload">{busy?'Okunuyor…':'Dosya veya dosyaları seç'}<input disabled={busy} type="file" accept=".pdf,.xlsx,.xls,.csv,.json" multiple onChange={loadFiles}/></label><button onClick={()=>updDownload('Islem-Sablonu.csv','\uFEFFTarih;Kurum;Kod;Varlık Türü;İşlem;Adet;Birim Fiyat;Nakit Tutarı;Ücret;Stopaj;Para Birimi;Saat\n','text/csv;charset=utf-8')}>İşlem şablonu</button><button onClick={()=>{const rows=[['Kurum','Kod','Varlık Türü','Adet','Ay Sonu Fiyatı','Para Birimi','Saf Gram / Adet'],...draft.positions.map(p=>[p.platform,p.code,p.group,p.qty,'',p.native,p.grams||''])];updDownload('Ay-Sonu-Pozisyonlari.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\n'),'text/csv;charset=utf-8')}}>Fiyat/adet şablonu</button></div>{uploadStatus&&<div className={'pt-update-notice pt-upload-result pt-upload-result-'+uploadStatus.state} role={uploadStatus.state==='error'?'alert':'status'} aria-live="polite" data-upload-feedback="true" aria-busy={busy}><strong>{uploadStatus.text}</strong>{uploadStatus.results.map((r,i)=><div className="pt-update-file" key={i}><strong>{r.state==='success'?'Taslağa alındı':r.state==='error'?'Alınmadı':'Kontrol gerekli'} · {r.name}</strong><p>{r.text}</p>{r.codes?.length>0&&<p className="pt-note">Varlıklar: {r.codes.join(', ')}</p>}{r.messages?.map((m,j)=><p key={j}>{m}</p>)}</div>)}{(uploadStatus.added>0||uploadStatus.updated>0||uploadStatus.payments>0)&&<div className="pt-update-actions"><button onClick={()=>document.getElementById('pt-update-trades')?.scrollIntoView({behavior:'smooth',block:'start'})}>Alınan işlemlere git</button><button onClick={()=>document.getElementById('pt-update-positions')?.scrollIntoView({behavior:'smooth',block:'start'})}>Adet ve fiyatlara git</button><button onClick={()=>document.getElementById('pt-update-review')?.scrollIntoView({behavior:'smooth',block:'start'})}>Son kontrole git</button></div>}</div>}{pendingUploads.length>0&&<div className="pt-update-notice"><p>Yalnız tanınamayan {pendingUploads.length} dosya için kurum seç:</p><label>Kurum<select aria-label="Belirsiz dosyanın kurumu" value={importPlatform} onChange={e=>setImportPlatform(e.target.value)}><option value="auto">Kurum seç</option>{UPD_PLATFORMS.slice(0,3).map(p=><option key={p}>{p}</option>)}</select></label><button disabled={busy||importPlatform==='auto'} onClick={()=>loadFiles({target:{files:pendingUploads,value:''}},importPlatform)}>Bu dosyaları tekrar oku</button></div>}{uploadStatus?.restoreReady&&restore&&<div className="pt-update-notice"><p>{restore.draft?restore.draft.period+' taslağı · '+restore.draft.trades.length+' işlem · '+restore.draft.positions.length+' pozisyon. Onaylarsan mevcut taslağın yerini alır.':'Veri yedeği tanındı. Yalnız eksik aylar eklenir; mevcut aylar değiştirilmez.'}</p><button onClick={()=>{restoreBackup();setUploadStatus(null)}}>Geri yüklemeyi onayla</button><button onClick={()=>{setRestore(null);setUploadStatus(null)}}>Vazgeç</button></div>}{draft.custody?.length>0&&<details><summary>MKK teyitleri · {draft.custody.length} kayıt</summary><p className="pt-note">Adet ve takas teyididir; bu kayıtlar yeni alış/satış sayılmaz. Hesap numaraları saklanmaz.</p><div className="pt-scroll"><table className="pt-table"><thead><tr><th>Tarih</th><th>Varlık / ISIN</th><th>Adet</th><th>Gönderen → Alan</th><th>Hareket</th></tr></thead><tbody>{draft.custody.map((r,i)=><tr key={i}><td>{r.date}</td><td>{r.code||r.isin}</td><td>{number(r.qty,9)}</td><td>{r.from} → {r.to}</td><td>{r.description}</td></tr>)}</tbody></table></div></details>}{draft.files.map((f,i)=><div className="pt-update-file" key={f.hash}><strong>{f.name}</strong><span>{f.imported} kayıt · {f.ignored} kapsam dışı · {f.duplicates} tekrar</span>{f.messages?.map((m,j)=><p key={j}>{m}</p>)}{f.unresolved&&<label><input type="checkbox" checked={!!f.resolved} onChange={e=>change(d=>{d.files[i].resolved=e.target.checked})}/>Bu dosyanın hareketlerini başka kaynaktan veya elle tamamladım; okunmayan satırları kontrol ettim.</label>}</div>)}</section>
 <section className="pt-card" id="pt-update-trades"><h3>Alım / satış ekle</h3><form onSubmit={addTrade}><div className="pt-update-fields"><TradeAssetPicker positions={draft.positions} onPick={choice=>{if(choice.kind==='metal'){setEntry(v=>({...v,platform:'Fiziki Altın',group:'Kıymetli Madenler',currency:'TRY',goldProduct:choice.product,goldPurity:'',qty:'',price:'',amount:''}));return}if(choice.kind==='manual'){const query=choice.query.trim();setEntry(v=>({...emptyTrade,date:v.date,side:v.side,code:/^[A-Za-z0-9.]{2,12}$/.test(query)?query.toUpperCase():'',name:query}));return}const p=choice.position;setEntry(v=>({...v,code:p.code,name:p.name,platform:p.platform,group:p.group,currency:p.native,grams:p.grams||'',unit:p.unit||null,purity:p.purity||null,metal:p.metal||null,goldProduct:p.platform==='Fiziki Altın'?'existing':v.goldProduct,goldPurity:p.purity?String(p.purity):'',qty:'',price:'',amount:''}))}}/>{input('Tarih','date','date')}<label>Saat (varsa)<input type="time" step="1" value={entry.time} onChange={e=>setEntry(v=>({...v,time:e.target.value}))}/></label>{entry.platform==='Fiziki Altın'?<><label>Altın / gümüş türü<select aria-label="Maden türü" value={entry.goldProduct} onChange={e=>setEntry(v=>({...v,goldProduct:e.target.value,goldPurity:'',qty:'',price:'',amount:''}))}>{entry.goldProduct==='existing'&&<option value="existing">{entry.code} · Mevcut kayıt</option>}{UPD_GOLD_PRODUCTS.map(p=><option key={p.id} value={p.id}>{p.label}</option>)}</select></label>{metalSpec?.needsPurity&&<label>Ayar / milyem<select required aria-label="Maden saflığı" value={entry.goldPurity} onChange={e=>setEntry(v=>({...v,goldPurity:e.target.value}))}><option value="">Ürün üzerindeki ayarı seç</option>{(metalSpec.metal==='silver'?UPD_SILVER_PURITY:UPD_GOLD_PURITY).map(p=><option key={p.value} value={p.value}>{p.label}</option>)}</select></label>}</>:<>{input('Kod','code')}{input('Adı','name')}</>}<label>Kurum<select aria-label="İşlem kurumu" value={entry.platform} onChange={e=>setEntry(v=>({...v,platform:e.target.value,group:e.target.value==='Fiziki Altın'?'Kıymetli Madenler':e.target.value==='Midas Kripto'?'Bitcoin':v.group,currency:e.target.value==='Fiziki Altın'?'TRY':v.currency,goldProduct:v.goldProduct==='existing'?'gram':v.goldProduct}))}>{UPD_PLATFORMS.map(p=><option key={p} value={p}>{p==='Fiziki Altın'?'Fiziki Altın / Gümüş':p}</option>)}</select></label><label>Varlık türü<select value={entry.group} onChange={e=>setEntry(v=>({...v,group:e.target.value}))}>{UPD_GROUPS.map(p=><option key={p}>{p}</option>)}</select></label><label>İşlem<select value={entry.side} onChange={e=>setEntry(v=>({...v,side:e.target.value}))}><option value="A">Alım</option><option value="S">Satış</option></select></label><label>Para birimi<select value={entry.currency} onChange={e=>setEntry(v=>({...v,currency:e.target.value}))}><option value="TRY">TL</option><option value="USD">USD</option></select></label>{input(metalSpec?(metalSpec.unit==='adet'?'Adet':'Ağırlık (gram)'):'Adet','qty')}{input(metalSpec?(metalSpec.unit==='adet'?'Adet başına fiyat (TL)':'Gram başına fiyat (TL)'):'Birim fiyat','price')}{input('Kesinti sonrası nakit tutarı','amount')}{input('Tutara dahil işlem ücreti','fee')}{input('Satışta kesilen stopaj','tax')}</div><button type="button" onClick={()=>{const qty=updNum(entry.qty),price=updNum(entry.price),fee=updNum(entry.fee),tax=updNum(entry.tax);if([qty,price,fee,tax].every(Number.isFinite))setEntry(v=>({...v,amount:String(Math.round((qty*price+(v.side==='A'?fee:-fee-tax))*100)/100)}))}}>Nakit tutarını hesapla</button><button type="submit">İşlemi taslağa ekle</button>{metalSpec&&<p className="pt-note">{metalSpec.legacy?'Mevcut bileziklerin her biri 10 gramdır; miktar toplam gram olarak girilir. Kayıtlı saf altın karşılığı ve eski maliyetler korunur. Farklı ayarda yeni bilezik için “Bilezik” türünü seç.':metalSpec.unit==='gram'?'Miktar tartılan brüt gramdır. Saf maden karşılığı ayar/milyemden hesaplanır. Ödediğin toplam tutara işçilik dahilse maliyette korunur.':'Miktar adettir; sabit saf altın karşılığıyla değerlenir. Mevcut çeyrek kaydının değerleme katsayısı korunur.'}</p>}</form><p className="pt-note">Nakit tutarı alışta ödediğin, satışta eline geçen tutardır. Komisyon ve stopaj ayrıca tekrar düşülmez. Virman/bedelsiz gibi adet değişikliklerini alım olarak girme; eşleşmeyen adet ay kapanışını durdurur.</p>{draft.trades.length>0&&<div className="pt-scroll"><table className="pt-table"><thead><tr><th>Tarih</th><th>Varlık</th><th>İşlem</th><th>Miktar</th><th>Birim fiyat</th><th>Net nakit</th><th>Ücret</th><th>Stopaj</th><th>Saat</th><th/></tr></thead><tbody>{draft.trades.map((t,i)=>{const position=draft.positions.find(p=>updKey(p)===updKey(t)),q=updDraftQuantity(position||t);return <tr key={i}><td>{t.date}</td><td>{t.code}<small>{t.currency} · {t.platform}{t.platform==='Fiziki Altın'?' / '+q.unit:''}</small></td><td>{t.side==='A'?'Alım':'Satış'}</td>{['qty','price','amount','fee','tax','time'].map(k=><td key={k}><input aria-label={t.code+' işlem '+(i+1)+' '+({qty:'adedi',price:'birim fiyatı',amount:'net tutarı',fee:'ücreti',tax:'stopajı',time:'saati'})[k]} value={k==='qty'?(t.qtyInput??number(updNum(t.qty)*q.scale,9).replace(/\./g,'')):k==='price'?(t.priceInput??String(updNum(t.price)/q.scale).replace('.',',')):t[k]??''} onChange={e=>change(d=>{if(k==='qty'){d.trades[i].qtyInput=e.target.value;d.trades[i].qty=updNum(e.target.value)/q.scale}else if(k==='price'){d.trades[i].priceInput=e.target.value;d.trades[i].price=updNum(e.target.value)*q.scale}else d.trades[i][k]=e.target.value})}/></td>)}<td><button aria-label={t.code+' işlemini kaldır'} onClick={()=>change(d=>{d.trades.splice(i,1);for(const p of d.positions)p.confirmed=false})}>Kaldır</button></td></tr>})}</tbody></table></div>}</section>
 <section className="pt-card"><h3>Temettü ekle</h3>{DIVIDEND_ROWS.filter(r=>r.date.startsWith(draft.period)).map(r=><p className="pt-note" key={r.id}>Arşivde zaten kayıtlı: {r.date} · {r.code} · {number(r.amount,2)} {r.currency}. Yeniden ekleme.</p>)}<form onSubmit={e=>{e.preventDefault();change(d=>{d.income.push({...pay,source:'Elle girilen temettü'})});setPay({...pay,code:'',qty:'',amount:''})}}><div className="pt-update-fields">{[['date','Tarih'],['code','Hisse / VOO kodu'],['qty','Temettüye esas adet'],['amount','Hesaba geçen net tutar']].map(([k,l])=><label key={k}>{l}<input required type={k==='date'?'date':'text'} value={pay[k]} onChange={e=>setPay(v=>({...v,[k]:e.target.value}))}/></label>)}<label>Para birimi<select value={pay.currency} onChange={e=>setPay(v=>({...v,currency:e.target.value}))}><option value="TRY">TL</option><option value="USD">USD</option></select></label></div><button type="submit">Temettüyü ekle</button></form>{draft.income.map((r,i)=><p key={i}>{r.date} · {r.code} · {r.amount} {r.currency} <label>Temettüye esas adet <input aria-label={r.code+' temettü adedi'} value={r.qty} onChange={e=>change(d=>{d.income[i].qty=e.target.value})}/></label> <button onClick={()=>change(d=>d.income.splice(i,1))}>Kaldır</button></p>)}</section>
 <section className="pt-card" id="pt-update-positions"><h3>Ay sonu adet ve fiyat kontrolü</h3><p className="pt-note">İşlem eklenince adet önerisi hesaplanır. Her adedi ekstreyle karşılaştır ve ay sonu birim fiyatını gir. Tamamı satılan varlığı 0 adetle bırak. Gram altın ve yeni bilezikler gramla, sarrafiye adetle gösterilir. Mevcut bileziklerin her biri 10 gram kabul edilerek toplam gram gösterilir.</p><div className="pt-update-actions"><input aria-label="Taslak varlık ara" placeholder="Kod veya isim ara" value={filter} onChange={e=>setFilter(e.target.value)}/><button onClick={()=>change(d=>{d.positions.filter(p=>p.platform==='Fiziki Altın').forEach(p=>{const g=updNum(p.metal==='silver'?d.market.silver:d.market.gold);if(!(g>0))return;p.price=String(g*updNum(p.grams));delete p.priceInput;p.confirmed=false})})}>Fiziki madenleri gram fiyatıyla değerle</button><button onClick={()=>change(d=>{for(const p of d.positions)if(Number.isFinite(updNum(p.qty))&&updNum(p.qty)>=0&&(updNum(p.qty)===0||updNum(p.price)>0))p.confirmed=true})}>Dolu adet/fiyatları kontrol ettim</button></div><div className="pt-scroll"><table className="pt-table"><thead><tr><th>Varlık</th><th>Ay sonu miktar</th><th>Birim fiyat</th><th>Kontrol</th></tr></thead><tbody>{draft.positions.map((p,i)=>!updIgnored(p)&&(!filter||(p.code+' '+p.name).toLocaleLowerCase('tr-TR').includes(filter.toLocaleLowerCase('tr-TR')))&&<tr key={updKey(p)}><td>{p.code}<small>{p.platform} · {p.native==='USD'?'USD':'TL'}{p.platform==='Fiziki Altın'?' / '+updDraftQuantity(p).unit:''}</small>{!updOpening().some(o=>updKey(o)===updKey(p))&&<select aria-label={p.code+' varlık türü'} value={p.group||''} onChange={e=>change(d=>{d.positions[i].group=e.target.value;for(const t of d.trades)if(updKey(t)===updKey(p))t.group=e.target.value})}><option value="">Varlık türünü seç</option>{UPD_GROUPS.map(g=><option key={g}>{g}</option>)}</select>}</td><td><input aria-label={p.code+' ay sonu adet '+p.platform} inputMode="decimal" value={p.qtyInput??number(updNum(p.qty)*updDraftQuantity(p).scale,9).replace(/\./g,'')} onChange={e=>change(d=>{d.positions[i].qtyInput=e.target.value;d.positions[i].qty=String(updNum(e.target.value)/updDraftQuantity(p).scale);d.positions[i].confirmed=false})}/></td><td><input aria-label={p.code+' ay sonu fiyat '+p.platform} inputMode="decimal" value={p.priceInput??(p.price===''?'':String(updNum(p.price)/updDraftQuantity(p).scale).replace('.',','))} onChange={e=>change(d=>{d.positions[i].priceInput=e.target.value;d.positions[i].price=String(updNum(e.target.value)*updDraftQuantity(p).scale);d.positions[i].confirmed=false})}/></td><td><input type="checkbox" aria-label={p.code+' doğrulandı '+p.platform} checked={!!p.confirmed} onChange={e=>change(d=>{d.positions[i].confirmed=e.target.checked})}/></td></tr>)}</tbody></table></div></section>
 <section className="pt-card" id="pt-update-review"><h3>Kontrol ve ayı kaydet</h3><label><input type="checkbox" checked={draft.reviewed} onChange={e=>setDraft(d=>({...d,reviewed:e.target.checked}))}/> Midas, İş Bankası, kripto, fiziki altın ve temettü hareketlerini tamamladım; ay sonu adet/fiyatlarını kaynaklarıyla karşılaştırdım.</label>{check.errors.length?<details open><summary>{check.errors.length} kontrol bekliyor</summary><ul>{check.errors.map((m,i)=><li key={i}>{m}</li>)}</ul></details>:<p className="pt-positive">Adet, işlem ve fiyat kontrolleri geçti. Toplam ₺{number(check.month.total_try,2)}.</p>}{check.warnings.map((m,i)=><p className="pt-note" key={i}>{m}</p>)}<label><input type="checkbox" checked={!!draft.anomaliesReviewed} onChange={e=>setDraft(d=>({...d,anomaliesReviewed:e.target.checked}))}/> Yukarıda belirtilen büyük fiyat/kur değişimleri varsa kaynaklarından ayrıca kontrol ettim.</label><br/><button disabled={busy||check.errors.length>0} onClick={close}>Kontrolleri geçen ayı kaydet</button><p className="pt-note">Kaydetmek bu cihazı günceller. Diğer cihazlara yansıtmak için aşağıdaki JSX’i indirip GitHub’a yükle.</p></section>
 <section className="pt-card"><h3>Güncel site dosyasını indir</h3><p>Son kullandığın PortfolioDashboard.jsx dosyasını şablon olarak seç. Geçmiş aylar ve tasarım korunarak yeni kayıtlar içine eklenir.</p><div className="pt-update-actions"><label className="pt-update-upload">JSX şablonunu seç<input type="file" accept=".jsx" onChange={sourceFile}/></label><button disabled={!source||busy} onClick={downloadJSX}>PortfolioDashboard.jsx indir</button></div><p className="pt-note">Şablon kodu çalıştırılmaz. Farklı sürüm veya daha yeni kayıt içeren şablonun üzerine yazılmaz. Site açıkken işlemler internetsiz yapılabilir; internet olmadan kapalı siteyi yeniden açmak için ayrıca çevrimdışı kurulum gerekir.</p></section></div>;
}

